import { useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import api from "@/lib/api";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

export default function ResetPassword() {
  const [params] = useSearchParams();
  const [password, setPassword] = useState("");
  const nav = useNavigate();
  const submit = async (e) => {
    e.preventDefault();
    try { await api.post("/auth/reset-password", { token: params.get("token"), password }); toast.success("Password reset. Please login."); nav("/login"); }
    catch (err) { toast.error(err?.response?.data?.detail || "Invalid or expired token"); }
  };
  return (
    <div className="max-w-md mx-auto px-4 py-14" data-testid="reset-page">
      <h1 className="font-display text-3xl font-bold text-center">Reset Password</h1>
      <form onSubmit={submit} className="bg-white border border-[#E6DFD5] rounded-2xl p-6 mt-6 card-shadow space-y-4">
        <Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="New password" required data-testid="reset-pwd" />
        <Button type="submit" className="btn-primary rounded-full w-full">Reset Password</Button>
      </form>
    </div>
  );
}
